        // Top processes by CPU — Stress page
        // ════════════════════════════════════════════════════════════════════
        private System.Windows.Threading.DispatcherTimer? _stressProcTimer;

        private void StartStressProcTimer()
        {
            _ = RefreshStressProcessesAsync();
            if (_stressProcTimer == null)
            {
                _stressProcTimer = new System.Windows.Threading.DispatcherTimer
                    { Interval = TimeSpan.FromSeconds(2) };
                _stressProcTimer.Tick += async (_, _) => await RefreshStressProcessesAsync();
            }
            _stressProcTimer.Start();
        }

        private void StopStressProcTimer() => _stressProcTimer?.Stop();

        private async Task RefreshStressProcessesAsync()
        {
            try
            {
                var snap = await _procMonitor.GetSnapshotAsync(15, light: true);
                await Dispatcher.InvokeAsync(() =>
                {
                    UpdateStressTopList(BuildGroupedByCpu(snap.TopByCpu, snap.TotalCpuPct)); // the Top processes card
                });
            }
            catch (Exception ex) { AppLogger.Warning(ex, "RefreshStressProcessesAsync"); }
        }


        // Group by exe for CPU — fraction = TotalCpuPct / system TotalCpuPct
        private static List<SMDWin.Models.GroupedProcessEntry> BuildGroupedByCpu(
            List<ProcessEntry> source, float totalCpuPct)
        {
            float sysTotal = Math.Max(1, totalCpuPct);
            return source
                .GroupBy(p => p.Name.ToLowerInvariant())
                .Select(g =>
                {
                    var instances = g.ToList();
                    var first = instances.First();
                    string display = !string.IsNullOrWhiteSpace(first.Description)
                        ? first.Description : first.Name;
                    float totalCpu = instances.Sum(p => p.CpuPct);
                    float totalRam = instances.Sum(p => p.RamMB);
                    return new SMDWin.Models.GroupedProcessEntry
                    {
                        ExeName       = first.Name,
                        DisplayName   = display,
                        TotalCpuPct   = totalCpu,
                        TotalRamMB    = totalRam,
                        InstanceCount = instances.Count,
                        Pid           = first.Pid,
                        AllPids       = instances.Select(p => p.Pid).ToList(),
                        Children      = instances,
                        CpuFraction   = Math.Min(1.0, totalCpu / 100.0),
                        RamFraction   = totalRam / Math.Max(1, 8192f)
                    };
                })
                .OrderByDescending(g => g.TotalCpuPct)
                .ToList();
        }


        private static T? FindAncestor<T>(DependencyObject d) where T : DependencyObject
        {
            var parent = System.Windows.Media.VisualTreeHelper.GetParent(d);
            while (parent != null && parent is not T)
                parent = System.Windows.Media.VisualTreeHelper.GetParent(parent);
            return parent as T;
        }

        private static char? TryGetChannelLetter(string slotLabel)
        {
            if (string.IsNullOrWhiteSpace(slotLabel)) return null;
            // "DIMM_A1", "DIMM-A2", "DIMM A1" — the letter right after "DIMM" and a separator.
            var m = System.Text.RegularExpressions.Regex.Match(slotLabel, @"DIMM[_\-\s]?([A-D])\d*", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            if (m.Success) return char.ToUpperInvariant(m.Groups[1].Value[0]);
            // "Channel A", "CHANNEL-B", "Chan A"
            m = System.Text.RegularExpressions.Regex.Match(slotLabel, @"CHAN(?:NEL)?[_\-\s]?([A-D])\b", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            if (m.Success) return char.ToUpperInvariant(m.Groups[1].Value[0]);
            // "P0 CHANNEL A DIMM 0" style (Dell/HP servers) already covered by the line above.
            return null;
        }
    }
